1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_THRESHOLD_YEARS = 2;
8	const FOLLOWUP_CONTRACT_DISCOUNT_RATE = 0.15;
9	const COMPONENT_BLOCK_BASE = 60;
10	const COMPONENT_BLOCK_SIZE = 3;
11	const DEDUCTIBLE_PER_DAMAGE = 100;
12	const CAP_MULTIPLIER = 2;
13	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
14	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
15	
16	const BASE_PREMIUM: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	
25	const INSURANCE_VALUE: Record<string, number> = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	};
33	
34	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
35	
36	type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
37	type Customer = { yearsWithMHPCO: number };
38	type QuoteStep = { op: "quote"; items: Item[] };
39	type Damage = { itemType: string; amount: number };
40	type ClaimStep = {
41	  op: "claim";
42	  policy: number;
43	  incident: { cause: string; damages: Damage[] };
44	};
45	type Step = QuoteStep | ClaimStep;
46	type Scenario = { customer: Customer; steps: Step[] };
47	
48	type QuoteResult = { premium: number };
49	type ClaimResult = { payout: number; remainingCap: number };
50	type StepResult = QuoteResult | ClaimResult;
51	
52	type Policy = { items: Item[]; remainingCap: number };
53	
54	const countByType = (items: Item[]): Map<string, number> =>
55	  items.reduce(
56	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
57	    new Map<string, number>(),
58	  );
59	
60	const basePremiumForGroup = (type: string, count: number): number =>
61	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
62	    ? COMPONENT_BLOCK_BASE
63	    : count * BASE_PREMIUM[type];
64	
65	const basePremiumForItems = (items: Item[]): number =>
66	  [...countByType(items)].reduce(
67	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
68	    0,
69	  );
70	
71	const surchargeRateForItem = (item: Item): number =>
72	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
73	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
74	
75	const itemSurcharges = (items: Item[]): number =>
76	  items.reduce(
77	    (sum, item) => sum + BASE_PREMIUM[item.type] * surchargeRateForItem(item),
78	    0,
79	  );
80	
81	const roundUpForInsurer = (premium: number): number => Math.ceil(premium);
82	const roundDownForInsurer = (payout: number): number => Math.floor(payout);
83	
84	const loyaltyDiscountRate = (customer: Customer): number =>
85	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
86	
87	const followupDiscountRate = (quoteIndex: number): number =>
88	  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;
89	
90	const withPolicyWideModifiers = (
91	  base: number,
92	  customer: Customer,
93	  quoteIndex: number,
94	): number =>
95	  base +
96	  base * FIRST_INSURANCE_SURCHARGE_RATE -
97	  base * loyaltyDiscountRate(customer) -
98	  base * followupDiscountRate(quoteIndex);
99	
100	const quotePremium = (
101	  { items }: QuoteStep,
102	  customer: Customer,
103	  quoteIndex: number,
104	): number =>
105	  roundUpForInsurer(
106	    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
107	      itemSurcharges(items),
108	  ) + PROCESSING_FEE;
109	
110	const insuranceSumFor = (items: Item[]): number =>
111	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
112	
113	const policyFrom = (items: Item[]): Policy => ({
114	  items,
115	  remainingCap: insuranceSumFor(items) * CAP_MULTIPLIER,
116	});
117	
118	const reimbursementRateFor = (item: Item): number =>
119	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD ? HIGH_ENCHANTMENT_PAYOUT_RATE : 1;
120	
121	const payoutForDamage = (item: Item, amount: number): number =>
122	  roundDownForInsurer(Math.max(0, amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE));
123	
124	const insuredItemFor = (items: Item[], damage: Damage): Item =>
125	  items.find((item) => item.type === damage.itemType)!;
126	
127	const totalPayoutFor = (items: Item[], damages: Damage[]): number =>
128	  damages.reduce(
129	    (sum, damage) => sum + payoutForDamage(insuredItemFor(items, damage), damage.amount),
130	    0,
131	  );
132	
133	const applyClaim = (
134	  policy: Policy,
135	  step: ClaimStep,
136	): { policy: Policy; result: ClaimResult } => {
137	  const payout = Math.min(totalPayoutFor(policy.items, step.incident.damages), policy.remainingCap);
138	  const remainingCap = policy.remainingCap - payout;
139	  return { policy: { ...policy, remainingCap }, result: { payout, remainingCap } };
140	};
141	
142	export const runScenario = ({ customer, steps }: Scenario): { results: StepResult[] } => {
143	  const results: StepResult[] = [];
144	  const policies = new Map<number, Policy>();
145	  let quoteIndex = 0;
146	  steps.forEach((step, index) => {
147	    if (step.op === "quote") {
148	      results.push({ premium: quotePremium(step, customer, quoteIndex) });
149	      policies.set(index, policyFrom(step.items));
150	      quoteIndex += 1;
151	    } else {
152	      const { policy, result } = applyClaim(policies.get(step.policy)!, step);
153	      policies.set(step.policy, policy);
154	      results.push(result);
155	    }
156	  });
157	  return { results };
158	};
